    'onState', 'needsWorkTree', 'showCommandWindow', 'trackFileChanges', 'streaming', 'autoFinish', 'agent', 'accountId', 'model', 'thinkingLevel', 'speedMode', 'permissionMode', 'prompt', 'command', 'phrases', 'userInput',
